import{_ as r,l,o as e,c as i,v as o,p as s,x as t,d as T,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"FFT","description":"","frontmatter":{"title":"FFT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fft.md","filePath":"cs/fft.md","lastUpdated":1789023840000}'),h={name:"cs/fft.md"};function c(_,a,m,u,f,F){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="fft" tabindex="-1">FFT <a class="header-anchor" href="#fft" aria-label="Permalink to &quot;FFT&quot;">​</a></h1><div class="epigraph"><p>多项式点值表示下乘法是逐点乘；DFT 把系数变成点值，$O(n\\log n)$ 而不是 $O(n^2)$ 的求值。</p><footer>—— 据 Cooley and Tukey, An Algorithm for the Machine Calculation of Complex Fourier Series, 1965；CLRS 第 30 章整理</footer></div><p>上一课<a href="/cs/karatsuba">Karatsuba</a>三次半长乘。多项式乘仍是卷积。缺口是 FFT：在单位根上求值与插值。不重写 Karatsuba 恒等式。后课 NTT 把复数换成模意义单位根。本课复数 DFT 的算法结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 次多项式系数乘：\\(c_k=\\sum_{i+j=k}a_i b_j\\)。点值：\\(C(\\omega^k)=A(\\omega^k)B(\\omega^k)\\)。DFT：\\(A(\\omega^k)=\\sum_j a_j \\omega^{jk}\\)。Cooley–Tukey：偶奇拆分，\\(T(n)=2T(n/2)+O(n)=O(n\\log n)\\)。卷积定理：循环卷积 = IDFT(DFT A · DFT B)。线性卷积把长度补到够，或补零。</p><p>缺口是蝶形，不是信号处理课的频谱物理。</p><h3 id="浮点误差" tabindex="-1">浮点误差 <a class="header-anchor" href="#浮点误差" aria-label="Permalink to &quot;浮点误差&quot;">​</a></h3><p>单位根是复数，浮点 FFT 乘大整数要选精度或改 NTT。本课算法正确性在精确算术；实现大数乘下一课。不要把数值噪声当卷积定义。</p><p><span class="marginnote">Cooley–Tukey 1965（Gauss 更早有同类分裂）。CLRS 30 写多项式 DFT。后课 NTT 服务精确卷积。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(n\\) 为 2 的幂。递归偶奇，或迭代位逆序 + 蝶形。逆变换：\\(\\omega^{-1}\\) 并除 \\(n\\)。卷积：补零到至少 \\(2n-1\\)。</p>',11)),(e(),s(p,null,{default:t(()=>[d(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COEF%5B%22%E7%B3%BB%E6%95%B0%22%5D%20--%3E%20DFT%5B%22DFT%20O(n%20log%20n)%22%5D%0A%20%20DFT%20--%3E%20PT%5B%22%E9%80%90%E7%82%B9%E4%B9%98%22%5D%0A%20%20PT%20--%3E%20IDFT%5B%22IDFT%22%5D%0A%20%20IDFT%20--%3E%20CONV%5B%22%E5%8D%B7%E7%A7%AF%20%2F%20%E5%A4%9A%E9%A1%B9%E5%BC%8F%E4%B9%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[T(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>位逆序实现细节不挡主线。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\omega^{n/2}=-1\\) 使偶奇拆分不重叠。与分治乘：都是 \\(O(n\\log n)\\) 与 \\(O(n^{1.585})\\) 的不同代数。圆周卷积有环绕，线性卷积须防。与矩阵：DFT 是 Vandermonde，直接乘 \\(O(n^2)\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Bluestein、不写实数打包全部技巧。不写卷积定理的连续傅里叶。后课默认：多项式乘可用 FFT \\(O(n\\log n)\\)（浮点）。下一课 NTT 精确模乘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DFT 求值 \\(O(n\\log n)\\)；卷积变逐点乘。</li><li>循环 vs 线性：补零。</li><li>大整数精确乘常改 NTT。</li><li>出处：Cooley and Tukey, 1965；CLRS 第 30 章。</li></ul>',7))])}const A=r(h,[["render",c]]);export{k as __pageData,A as default};
